def count_digit_7(n: int) -> int:
    """
    Counts occurrences of digit '7' in numbers <= n
    that are multiples of 11 or 13.
    """
    count = 0
    for num in range(1, n + 1):
        if num % 11 == 0 or num % 13 == 0:
            count += str(num).count('7')
    return count

def count_digit_7_functional(n: int) -> int:
