import sys

def circular_shift(s: str, shift: int) -> str:
    """
    Converts input to string. If shift exceeds length, reverses string.
    Otherwise, performs circular shift: moves last 'shift' characters to front.
    """
    s = str(s)
    n = len(s)

    if n == 0:
        return s

    if shift >= n:
        return s[::-1]

    return s[-shift:] + s[:-shift]

