def caesar_encode(text: str) -> str:
    """Encode a lowercase string using a Caesar shift of +5."""
    result = []
    for ch in text:
        if 'a' <= ch <= 'z':
            shifted = chr((ord(ch) - ord('a') + 5) % 26 + ord('a')))
            result.append(shifted)
        else:
            result.append(ch)
    return ''.join(result)

def caesar_decode(text: str) -> str:
    """Decode a lowercase string encoded with a Caesar shift of +5."""
    result = []
    for ch in text:
        if 'a' <= ch <= 'z':
            shifted = chr((ord(ch) - ord('a') - 5) % 26 + ord('a'))
            result.append(shifted)
        else:
            result.append(ch)
    return ''.join(result)

# Example usage
