def encode_cyclic(s: str) -> str:
    """
    Encodes a string by cyclically shifting each full 3-character group to the left.
    Partial groups remain unchanged.
    """
    def shift_group(chunk: str) -> str:
        return chunk[1:] + chunk[0] if len(chunk) == 3 else chunk

    return ''.join(
        shift_group(s[i:i+3])
        for i in range(0, len(s), 3)
    )

def decode_cyclic(s: str) -> str:
    """
    Decodes a string by cyclically shifting each full 3-character group to the right.
    Partial groups remain unchanged.
    """
    def shift_group(chunk: str) -> str:
        return chunk[-1] + chunk[:-1] if len(chunk) == 3 else chunk

    return ''.join(
        shift_group(s[i:i+3])
        for i in range(0, len(s), 3)
    )
